import React, { Component } from "react";
import PropTypes from "prop-types";
import Box from "@mui/material/Box";
import {Table,Button} from "@mui/material";
import TableBody from "@mui/material/TableBody";
import TableCell from "@mui/material/TableCell";
import TableContainer from "@mui/material/TableContainer";
import TableHead from "@mui/material/TableHead";
import TablePagination from "@mui/material/TablePagination";
import TableRow from "@mui/material/TableRow";
import TableSortLabel from "@mui/material/TableSortLabel";
import Paper from "@mui/material/Paper";
import { visuallyHidden } from "@mui/utils";
import {FaRegFilePdf} from "react-icons/fa";
import { IconButton, Typography } from "@mui/material";
import DeleteForeverIcon from '@mui/icons-material/DeleteForever';
import Tooltip, { tooltipClasses } from '@mui/material/Tooltip';
import { styled } from '@mui/material/styles';

const CustomTooltip = styled(({ className, ...props }) => (
    <Tooltip {...props} arrow classes={{ popper: className }} />
))(({ theme }) => ({
    [`& .${tooltipClasses.arrow}`]: {
      color: theme.palette.common.white
    },
    [`& .${tooltipClasses.tooltip}`]: {
      backgroundColor: theme.palette.common.white,
      color: '#1976d2',
      boxShadow: theme.shadows[1],
      fontSize: 16
    },
}));


export default class CustomizedTable extends Component {
    constructor(props) {
      super(props);
        this.state = {
            RowsData: props.Data,
            Columns: props.Columns,
            orderBy:"",order:"",
            rowsPerPage:10,page:0,selected:[],
            uniqueColumnName:props.uniqueColumnName, MultiSelect:props.MultiSelect
        }
    }
    
    componentDidMount(){
        console.log(this.props)
    }
    createSortHandler = (event,property) => {
        this.handleRequestSort(event, property);
    };
    handleRequestSort = (event, property) => {
        const isAsc = this.state.orderBy === property && this.state.order === "asc";
        this.setState({orderBy:property, order:isAsc?"desc":"asc"});
    };
    handleChangePage = (newPage) => {
        this.setState({page:newPage});
    };
    handleChangeRowsPerPage = (event) => {
        this.setState({page:0, rowsPerPage:parseInt(event.target.value, 10)});
    };
    stableSort(array, comparator) {
        const stabilizedThis = array.map((el, index) => [el, index]);
        stabilizedThis.sort((a, b) => {
            const order = comparator(a[0], b[0]);
            if (order !== 0) {
                return order;
            }
            return a[1] - b[1];
        });
        return stabilizedThis.map((el) => el[0]);
    }
    getComparator(order, orderBy) {
        return(order==="desc"?(a,b)=>this.descendingComparator(b,a,orderBy):(a,b)=>this.descendingComparator(a,b,orderBy));
    }
    descendingComparator(a, b, orderBy) {
        if (b[orderBy] < a[orderBy]) {
            return -1;
        }
        if (b[orderBy] > a[orderBy]) {
            return 1;
        }
        return 0;
    }
    isSelected=(id)=>this.state.selected.indexOf(id) !== -1;
    handleClick=async(event,Uniqueid, btn)=>{
        let SelectedIds = this.state.selected;
        const AlreadySelectedIndex = SelectedIds.indexOf(Uniqueid);
        if(AlreadySelectedIndex === -1){
            if(this.state.MultiSelect || SelectedIds.length===0){
                SelectedIds.push(Uniqueid);
            }else{
                SelectedIds[0]=Uniqueid;
            }
        }else{
            SelectedIds.splice(AlreadySelectedIndex,1);
        }
        await this.setState({selected: SelectedIds});
        this.props.getData(SelectedIds, btn)
    };

    render() {
        return (
            <Box sx={{ width: "100%" }}>
                <Paper sx={{ width: "100%", mb: 2 }}>
                    <TableContainer>
                        <Table
                            sx={{ minWidth: 750 }}
                            aria-labelledby="tableTitle"
                            // size={dense ? "small" : "medium"}
                        >
                            <TableHead style={{backgroundColor: "rgb(117, 159, 198)"}}>
                                <TableRow>
                                    {this.state.Columns.map((headCell) => (
                                        <TableCell
                                            key={headCell.id}
                                            align={"center"}
                                            sortDirection={this.state.orderBy === headCell.id ? this.state.order : false}
                                        >
                                            <TableSortLabel
                                                active={this.state.orderBy === headCell.id}
                                                direction={this.state.orderBy === headCell.id ? this.state.order : "asc"}
                                                onClick={(e)=>this.createSortHandler(e,headCell.id)}
                                            >
                                                <b>{headCell.label}
                                                {this.state.orderBy === headCell.id ? (
                                                    <Box component="span" sx={visuallyHidden}>
                                                        {this.state.order === "desc" ? "sorted descending" : "sorted ascending"}
                                                    </Box>
                                                ) : null}</b>
                                            </TableSortLabel>
                                        </TableCell>
                                    ))}
                                </TableRow>
                            </TableHead>
                            <TableBody>
                                {this.state.RowsData.length === 0?
                                    <TableRow>
                                        <TableCell colSpan={this.state.Columns.length} align="center">******* Data Not Found *******</TableCell>
                                    </TableRow>
                                :
                                    this.stableSort(this.state.RowsData, this.getComparator(this.state.order, this.state.orderBy)).slice(this.state.page * this.state.rowsPerPage, this.state.page * this.state.rowsPerPage + this.state.rowsPerPage).map((row,index)=>{
                                        const isItemSelected = this.isSelected(row[this.state.uniqueColumnName]);
                                        const labelId = `enhanced-table-checkbox-${index}`;
                                        return (
                                            <TableRow
                                                // hover
                                                // onClick={(event) => this.handleClick(event, row[this.state.uniqueColumnName])}
                                                role="checkbox"
                                                // aria-checked={isItemSelected}
                                                tabIndex={-1}
                                                key={row[this.state.uniqueColumnName]}
                                                // selected={isItemSelected}
                                                // style={{cursor:"pointer"}}
                                            >
                                                {this.state.Columns.map((data,CIndex)=>{
                                                    if(data.id===this.state.uniqueColumnName){
                                                        return(
                                                            <TableCell
                                                                component="th"
                                                                id={labelId}
                                                                scope="row"
                                                                padding="none"
                                                                align="center"
                                                                sx={{ px: 1 }}
                                                            >
                                                                {row[data.id]}
                                                            </TableCell>
                                                        )
                                                    }else if(data.id==="report"){
                                                        return(
                                                            <TableCell align="center">
                                                                <IconButton size="small" onClick={(event) => this.handleClick(event, row[this.state.uniqueColumnName])} color="primary">
                                                                    <FaRegFilePdf/>
                                                                </IconButton>
                                                            </TableCell>
                                                        )
                                                    }else if(data.id==="check"){
                                                        return(
                                                            <TableCell align="center">
                                                                {/* {row["excel_upload"]===1 || row["excel_upload"]===undefined? */}
                                                                    <Button size='small' variant="contained" onClick={(event) => this.handleClick(event, row[this.state.uniqueColumnName], "check_btn")}>{row["excel_upload"]===0?"Edit":"Check"}</Button>
                                                                    {/* <IconButton size="small" onClick={(event) => this.handleClick(event, row[this.state.uniqueColumnName])} color="primary">
                                                                        <FaRegFilePdf/>
                                                                    </IconButton> */}
                                                                
                                                            </TableCell>
                                                        )
                                                    }else{
                                                        return(
                                                            <TableCell align="center">{row[data.id]}</TableCell>
                                                        )
                                                    }
                                                })}
                                            </TableRow>
                                        )
                                    })
                                }
                            </TableBody>
                        </Table>
                    </TableContainer>
                    <TablePagination
                        rowsPerPageOptions={[5, 10, 25, 50, 100]}
                        component="div"
                        count={this.state.RowsData.length}
                        rowsPerPage={this.state.rowsPerPage}
                        page={this.state.page}
                        onPageChange={(event, newPage)=>this.handleChangePage(newPage)}
                        onRowsPerPageChange={(event)=>this.handleChangeRowsPerPage(event)}
                    />
                </Paper>
            </Box>
        )
    }
}